    } else {
        value+=(summary.flexible%2===0?70:-70)
    }
    value-=gameData.edgeCount[gameData.EDGE_WILL]*2
    return value
}

RolloutAI.prototype._safeCandidates=function(gameData,rootPlayer,limit){
    var edges=gameData.getAllEdges(gameData.EDGE_NOT)
